export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioOutput {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function quote(step: QuoteStep): QuoteResult {
  let premium = 0;

  for (const item of step.items) {
    const base = BASE_PREMIUMS[item.type];
    premium += base + base * FIRST_INSURANCE_SURCHARGE;
  }

  return { premium: premium + PROCESSING_FEE };
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return { results: scenario.steps.map(quote) };
}

