interface Policy {
  items: Item[];
  remainingCap: number;
}

function claim(step: ClaimStep, policy: Policy): ClaimResult {
  let payout = 0;

  for (const damage of step.incident.damages) {
    payout += Math.max(0, damage.amount - DEDUCTIBLE);
  }

  payout = Math.min(payout, policy.remainingCap);
  policy.remainingCap -= payout;

  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  let quoteCount = 0;
  const policies = new Map<number, Policy>();

  const results = scenario.steps.map((step, index) => {
    if (step.op === 'claim') {
      const policy = policies.get(step.policy)!;
      return claim(step, policy);
    }

    const result = quote(step, scenario.customer, quoteCount);
    quoteCount += 1;
    policies.set(index, {
      items: step.items,
      remainingCap:
        CAP_MULTIPLIER *
        step.items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0),
    });
    return result;
  });

  return { results };
}

